// Generated by exit-ramp. A Val Town std/email-shaped sender over Cloudflare Email Service (binding: EMAIL).
//
// Setup (https://developers.cloudflare.com/email-service/get-started/send-emails/):
//   1. Onboard a domain you control for Email Sending (Cloudflare DNS required).
//   2. Set the secret EXIT_RAMP_EMAIL_FROM to an address on that domain, e.g. "notifications@yourdomain.com".
//   3. Optional: EXIT_RAMP_EMAIL_TO is the default recipient. Val Town defaulted to the account owner; Workers has no owner.
// Differences from std/email: no default sender or recipient, and attachments take base64 content like Val Town but are sent
// as inline bytes here. An accepted API call does not prove delivery: send to a controlled inbox first.
import { env } from "cloudflare:workers";

type Addr = string | { email: string; name?: string };

export interface EmailOptions {
  to?: string | string[];
  cc?: string | string[];
  bcc?: string | string[];
  from?: Addr;
  replyTo?: Addr;
  subject?: string;
  text?: string;
  html?: string;
  attachments?: { content: string; filename: string; type?: string; disposition?: "attachment" | "inline"; contentId?: string }[];
  headers?: Record<string, string>;
}

const norm = (a: Addr): string | { name: string; email: string } => (typeof a === "string" ? a : { name: a.name ?? "", email: a.email });
const list = (v: string | string[] | undefined): string[] | undefined => (v === undefined ? undefined : Array.isArray(v) ? v : [v]);

function b64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export async function email(options: EmailOptions): Promise<{ messageId?: string }> {
  const e = env as unknown as { EMAIL?: SendEmail; EXIT_RAMP_EMAIL_FROM?: string; EXIT_RAMP_EMAIL_TO?: string };
  if (!e.EMAIL) throw new Error('No send_email binding named "EMAIL". Add [[send_email]] to wrangler.toml.');
  const from = options.from ?? e.EXIT_RAMP_EMAIL_FROM;
  if (!from) throw new Error("No sender. Pass `from` or set the EXIT_RAMP_EMAIL_FROM secret (an address on your onboarded domain).");
  const to = list(options.to) ?? (options.cc || options.bcc ? undefined : e.EXIT_RAMP_EMAIL_TO ? [e.EXIT_RAMP_EMAIL_TO] : undefined);
  const cc = list(options.cc);
  const bcc = list(options.bcc);
  if (!to?.length && !cc?.length && !bcc?.length) throw new Error("No recipient. Pass `to` or set the EXIT_RAMP_EMAIL_TO secret.");
  const attachments = options.attachments?.map((a) =>
    a.disposition === "inline"
      ? { disposition: "inline" as const, contentId: a.contentId ?? a.filename, filename: a.filename, type: a.type ?? "application/octet-stream", content: b64(a.content) }
      : { disposition: "attachment" as const, filename: a.filename, type: a.type ?? "application/octet-stream", content: b64(a.content) },
  );
  const message = {
    from: norm(from),
    to: to?.length ? to : (cc?.length ? cc : bcc!)[0],
    ...(cc?.length && to?.length ? { cc } : {}),
    ...(bcc?.length && to?.length ? { bcc } : {}),
    subject: options.subject ?? "Message from your Worker",
    ...(options.text !== undefined ? { text: options.text } : {}),
    ...(options.html !== undefined ? { html: options.html } : {}),
    ...(options.replyTo ? { replyTo: norm(options.replyTo) } : {}),
    ...(options.headers ? { headers: options.headers } : {}),
    ...(attachments ? { attachments } : {}),
  };
  const res = await e.EMAIL.send(message as Parameters<SendEmail["send"]>[0] & object);
  return { messageId: (res as { messageId?: string }).messageId };
}
